/*
 * prog20_anagram_checker
 *
 * Re‑implementation of the original binary’s functionality.
 * The program expects exactly two command‑line arguments.
 *
 *   USAGE        – printed when the number of arguments is not 2.
 *   TOO_LONG     – printed when either argument is 1025 characters or longer.
 *   ANAGRAM      – printed when the two strings are anagrams of each other
 *                  (ignoring spaces and case‑insensitively for letters).
 *   NOT_ANAGRAM  – printed otherwise.
 *
 * The implementation follows the logic uncovered in the disassembly:
 *   * arguments are limited to < 1025 characters,
 *   * spaces are ignored,
 *   * letters are compared case‑insensitively (uppercase converted to lowercase),
 *   * all other characters are taken verbatim,
 *   * a frequency table of size 256 (one entry per possible byte value) is used.
 */

#include <stdio.h>
#include <string.h>

#define MAX_LEN 1024          /* maximum allowed length (strictly less than 1025) */

int main(int argc, char *argv[])
{
    /* Argument count handling */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    /* Length checks (must be < 1025) */
    if (strlen(s1) >= MAX_LEN + 1 || strlen(s2) >= MAX_LEN + 1) {
        puts("TOO_LONG");
        return 0;
    }

    /* Build frequency tables (ignoring spaces, case‑insensitive for letters) */
    int cnt1[256] = {0};
    int cnt2[256] = {0};

    for (const unsigned char *p = (const unsigned char *)s1; *p != '\0'; ++p) {
        if (*p == ' ')
            continue;                       /* spaces are ignored */
        unsigned char c = *p;
        if ('A' <= c && c <= 'Z')
            c = (unsigned char)(c + 32);    /* convert to lower case */
        cnt1[c]++;
    }

    for (const unsigned char *p = (const unsigned char *)s2; *p != '\0'; ++p) {
        if (*p == ' ')
            continue;                       /* spaces are ignored */
        unsigned char c = *p;
        if ('A' <= c && c <= 'Z')
            c = (unsigned char)(c + 32);    /* convert to lower case */
        cnt2[c]++;
    }

    /* Compare the two tables */
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) {
            puts("NOT_ANAGRAM");
            return 0;
        }
    }

    puts("ANAGRAM");
    return 0;
}
